AFRAME.registerComponent('art-canvas',{
 init(){
  const T=AFRAME.THREE;this.canvas=document.createElement('canvas');this.canvas.width=1024;this.canvas.height=640;this.ctx=this.canvas.getContext('2d');this.color='#527d75';this.size=12;this.mode='brush';this.portraitVariation=0;this.portraitLook=0;this.drawing=false;this.strokes=0;this.paths=[];this.activePath=null;this.undoStack=[];this.paths=[];this.ctx.fillStyle='#fffdf6';this.ctx.fillRect(0,0,1024,640);this.texture=new T.CanvasTexture(this.canvas);this.texture.colorSpace=T.SRGBColorSpace;this.texture.anisotropy=4;this.texture.needsUpdate=true;
  this.apply=()=>{if(window.GlobiquestPanelInput&&!this.el.__panelInput)window.GlobiquestPanelInput.bind(this.el,1,1,[{x:0,y:0,w:1,h:1,label:'Draw on canvas',draw:true,action:()=>{}}]);const mesh=this.el.getObject3D('mesh');if(mesh){mesh.material.map=this.texture;mesh.material.needsUpdate=true}};
  this.down=e=>{this.source=e.detail?.cursorEl||this.el.sceneEl;const hit=e.detail?.intersection||this.source.components?.raycaster?.getIntersection(this.el)||this.el.sceneEl.components.raycaster?.getIntersection(this.el);const uv=hit?.uv;if(!uv)return;const camera=document.getElementById('camera');if(!this.el.sceneEl.is('vr-mode')){this.lookWasEnabled=camera?.getAttribute('look-controls')?.enabled!==false;camera?.setAttribute('look-controls','enabled',false);}this.checkpoint();if(this.mode==='brush'){this.drawing=true;this.last=null;this.activePath={color:this.color,size:this.size,points:[]};this.paths.push(this.activePath);this.paint(uv)}else this.stamp(uv);this.strokes++;};
  this.up=()=>{this.drawing=false;this.last=null;if(this.lookWasEnabled!==undefined){document.getElementById('camera')?.setAttribute('look-controls','enabled',this.lookWasEnabled);this.lookWasEnabled=undefined}};this.el.addEventListener('loaded',this.apply);this.el.addEventListener('mousedown',this.down);this.el.sceneEl.addEventListener('mouseup',this.up);window.addEventListener('pointerup',this.up);window.addEventListener('pointercancel',this.up);window.addEventListener('blur',this.up);for(const hand of ['leftHand','rightHand'])document.getElementById(hand)?.addEventListener('triggerup',this.up);if(this.el.hasLoaded)this.apply();
 },
 tick(){if(!this.drawing)return;const raycaster=this.source?.components?.raycaster||this.el.sceneEl.components.raycaster;const hit=raycaster?.getIntersection(this.el);if(hit?.uv)this.paint(hit.uv);else this.last=null},
 beautify(style='art'){if(!this.strokes&&style!=='portrait'){if(typeof notify==='function')notify('Draw a scribble first, then choose a style.');return false}if(!window.GlobiquestSketchStyles)return false;this.up();this.checkpoint();const source=document.createElement('canvas');source.width=1024;source.height=640;source.getContext('2d').drawImage(this.canvas,0,0);window.GlobiquestSketchStyles.render(this.canvas,source,this.paths,style,this.color,style==='portrait'?{variation:this.portraitVariation++,look:this.portraitLook}:undefined);this.strokes++;this.texture.needsUpdate=true;if(typeof notify==='function')notify((style==='portrait'?'New portrait '+this.portraitVariation:'Art style')+' created locally. Undo restores your previous artwork.');return true},
 cyclePortraitLook(){this.portraitLook=(this.portraitLook+1)%4;const name=['Watercolour','Ink','Pop','Storybook'][this.portraitLook];if(typeof notify==='function')notify('Portrait look: '+name+'. Select New portrait to create.');return name},
 point(uv){return{x:Math.max(0,Math.min(1024,uv.x*1024)),y:Math.max(0,Math.min(640,(1-uv.y)*640))}},
 paint(uv){const p=this.point(uv),c=this.ctx;if(this.activePath&&(!this.activePath.points.length||Math.hypot(p.x-this.activePath.points.at(-1).x,p.y-this.activePath.points.at(-1).y)>2))this.activePath.points.push({...p});c.strokeStyle=this.color;c.fillStyle=this.color;c.lineWidth=this.size;c.lineCap=c.lineJoin='round';if(this.last){c.beginPath();c.moveTo(this.last.x,this.last.y);c.lineTo(p.x,p.y);c.stroke()}else{c.beginPath();c.arc(p.x,p.y,this.size/2,0,Math.PI*2);c.fill()}this.last=p;this.texture.needsUpdate=true},
 stamp(uv){const p=this.point(uv),c=this.ctx,s=this.size*3;this.paths.push({type:this.mode,color:this.color,size:s,point:{...p}});c.fillStyle=this.color;c.beginPath();if(this.mode==='sun')c.arc(p.x,p.y,s,0,Math.PI*2);else if(this.mode==='mountain'){c.moveTo(p.x,p.y-s);c.lineTo(p.x+s,p.y+s*.7);c.lineTo(p.x-s,p.y+s*.7);c.closePath()}else{c.moveTo(p.x,p.y-s);c.lineTo(p.x+s*.8,p.y+s*.45);c.lineTo(p.x-s*.8,p.y+s*.45);c.closePath();c.fillRect(p.x-s*.11,p.y+s*.4,s*.22,s*.5)}c.fill();this.texture.needsUpdate=true},
 checkpoint(){this.undoStack.push({data:this.canvas.toDataURL('image/png'),strokes:this.strokes,paths:JSON.parse(JSON.stringify(this.paths))});if(this.undoStack.length>10)this.undoStack.shift()},
 undo(){const previous=this.undoStack.pop();if(!previous)return;this.drawing=false;const image=new Image();image.onload=()=>{if(this.disposed)return;this.ctx.clearRect(0,0,1024,640);this.ctx.drawImage(image,0,0);this.strokes=previous.strokes;this.paths=previous.paths||[];this.activePath=null;this.texture.needsUpdate=true};image.src=previous.data},
 clear(){this.checkpoint();this.drawing=false;this.strokes=0;this.paths=[];this.activePath=null;this.ctx.fillStyle='#fffdf6';this.ctx.fillRect(0,0,1024,640);this.texture.needsUpdate=true},
 load(data){this.paths=[];this.activePath=null;const image=new Image();image.onload=()=>{if(this.disposed)return;this.ctx.drawImage(image,0,0,1024,640);this.strokes=1;this.texture.needsUpdate=true};image.src=data},
 remove(){this.up();this.disposed=true;this.el.removeEventListener('loaded',this.apply);this.el.removeEventListener('mousedown',this.down);this.el.sceneEl.removeEventListener('mouseup',this.up);window.removeEventListener('pointerup',this.up);window.removeEventListener('pointercancel',this.up);window.removeEventListener('blur',this.up);for(const hand of ['leftHand','rightHand'])document.getElementById(hand)?.removeEventListener('triggerup',this.up);this.texture.dispose()}
});
